window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9b642fb2dfc41c15"]={"versions": [{"id": "FIG-9b642fb2dfc41c15", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Ablaufdiagramm zur Veranschaulichung des Übertragungsmodus „Mixed“ (periodisch mit ereignisgesteuertem Anteil / n-facher Wiederholung) und Umschaltung des Transmission Mode Selector (TMS) im AUTOSAR Communication Modul (AUTOSAR COM, Classic Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitachse</strong>: Horizontale Hauptzeitachse mit Unterbrechungssymbolen (Auslassungen).</li>\n<li><strong>Zustände / Werte</strong>: Signal-/Filterzustand $V = a$ bzw. $V = b$ steuert den aktiven Transmission Mode.</li>\n<li><strong>Sendeereignisse</strong>: Grüne Pfeile (vertikal nach unten) für I-PDU-Übertragungszeitpunkte auf den Bus.</li>\n<li><strong>Auslöser / Trigger</strong>: Rote Blitzsymbole für interne Sendeanforderungen (Ereignisse / Signalaktualisierungen).</li>\n<li><strong>Zeitparameter</strong>:</li>\n<li>$t_{c1}$, $t_{c2}$: Zykluszeiten (Cycle Times) der periodischen Übertragung für die jeweiligen Modi.</li>\n<li>$y \\cdot t_{c1}$, $z \\cdot t_{c2}$: Ganzzahlige Vielfache von Übertragungszyklen zwischen den dargestellten Zeitausschnitten.</li>\n<li>$t_d$: Wiederholzeit (Repetition Period / Delay) für n-fache Bursts ($n = 3$).</li>\n<li>$dt$: Übertragungsdauer / Laufzeit (Transmission Duration).</li>\n<li>$t_{r,\\min}$: Mindestabstandszeit (Minimum Delay Time, MDT) zur Begrenzung der Buslast.</li>\n<li><strong>Sonderdarstellung</strong>: Blau gestrichelter Pfeil markiert einen regulären periodischen Sendezeitpunkt, der durch ein nachfolgendes oder überlappendes Ereignis angepasst wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initiale periodische Aussendung ($V = a$)</strong>: Das I-PDU wird zyklisch im Abstand von $t_{c1}$ übertragen.</li>\n<li><strong>TMS-Umschaltung auf Modus $b$ ($V = b$)</strong>: Ein Signalereignis triggert den Moduswechsel zu $V = b$. Die Übertragung erfolgt nun nach Ablauf der Mindestabstandszeit $t_{r,\\min}$ mit der neuen Zykluszeit $t_{c2}$.</li>\n<li><strong>TMS-Umschaltung zurück auf Modus $a$ mit Burst ($V = a$)</strong>: Ein Ereignis schaltet den Modus zurück auf $a$. Nach Ablauf von $dt$ und Einhaltung von $t_{r,\\min}$ wird ein 3-facher Burst ($n = 3$) mit dem Wiederholabstand $t_d$ gesendet. Anschließend schließt die periodische Übertragung mit Zyklus $t_{c1}$ direkt an den letzten Burst-Pfeil an.</li>\n<li><strong>Ereignis während laufendem Zyklus ($V = a$)</strong>: Ein erneutes Ereignis führt nach $dt$ und $t_{r,\\min}$ zu einem weiteren 3-fachen Burst ($t_d$). Der ursprüngliche zyklische Sendezeitpunkt (blau gestrichelt) wird durch den vorangegangenen Burst abgelöst bzw. der Zyklus $t_{c1}$ wird neu synchronisiert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Veranschaulicht normativ die Einhaltung der Minimum Delay Time ($t_{r,\\min}$) sowohl bei Moduswechseln (TMS-Switch) als auch bei ereignisgesteuerten Burst-Wiederholungen im Mixed-Modus.</li>\n<li>Zeigt das deterministische Verhalten für AUTOSAR COM: Ein durch ein Ereignis ausgelöster Burst ($n$ Wiederholungen im Abstand $t_d$) hat Vorrang; nach Abschluss des Bursts wird der periodische Zyklus $t_c$ neu gestartet bzw. weitergeführt.</li>\n<li>Bei der Implementierung ist sicherzustellen, dass keine Aussendung die konfigurierte Mindestzeit $t_{r,\\min}$ unterschreitet, selbst wenn ein periodischer Trigger oder Ereignis-Trigger unmittelbar ansteht.</li>\n</ul>"}, {"id": "FIG-40c0bbdc2d3a7cee", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Ablaufdiagramm zur Veranschaulichung des Übertragungsmodus „Mixed“ (periodisch mit ereignisgesteuertem Anteil / n-facher Wiederholung) und Umschaltung des Transmission Mode Selector (TMS) im AUTOSAR Communication Modul (AUTOSAR COM, Classic Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitachse</strong>: Horizontale Hauptzeitachse mit Unterbrechungssymbolen (Auslassungen).</li>\n<li><strong>Zustände / Werte</strong>: Signal-/Filterzustand $V = a$ bzw. $V = b$ steuert den aktiven Transmission Mode.</li>\n<li><strong>Sendeereignisse</strong>: Grüne Pfeile (vertikal nach unten) für I-PDU-Übertragungszeitpunkte auf den Bus.</li>\n<li><strong>Auslöser / Trigger</strong>: Rote Blitzsymbole für interne Sendeanforderungen (Ereignisse / Signalaktualisierungen).</li>\n<li><strong>Zeitparameter</strong>:</li>\n<li>$t_{c1}$, $t_{c2}$: Zykluszeiten (Cycle Times) der periodischen Übertragung für die jeweiligen Modi.</li>\n<li>$y \\cdot t_{c1}$, $z \\cdot t_{c2}$: Ganzzahlige Vielfache von Übertragungszyklen zwischen den dargestellten Zeitausschnitten.</li>\n<li>$t_d$: Wiederholzeit (Repetition Period / Delay) für n-fache Bursts ($n = 3$).</li>\n<li>$dt$: Übertragungsdauer / Laufzeit (Transmission Duration).</li>\n<li>$t_{r,\\min}$: Mindestabstandszeit (Minimum Delay Time, MDT) zur Begrenzung der Buslast.</li>\n<li><strong>Sonderdarstellung</strong>: Blau gestrichelter Pfeil markiert einen regulären periodischen Sendezeitpunkt, der durch ein nachfolgendes oder überlappendes Ereignis angepasst wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initiale periodische Aussendung ($V = a$)</strong>: Das I-PDU wird zyklisch im Abstand von $t_{c1}$ übertragen.</li>\n<li><strong>TMS-Umschaltung auf Modus $b$ ($V = b$)</strong>: Ein Signalereignis triggert den Moduswechsel zu $V = b$. Die Übertragung erfolgt nun nach Ablauf der Mindestabstandszeit $t_{r,\\min}$ mit der neuen Zykluszeit $t_{c2}$.</li>\n<li><strong>TMS-Umschaltung zurück auf Modus $a$ mit Burst ($V = a$)</strong>: Ein Ereignis schaltet den Modus zurück auf $a$. Nach Ablauf von $dt$ und Einhaltung von $t_{r,\\min}$ wird ein 3-facher Burst ($n = 3$) mit dem Wiederholabstand $t_d$ gesendet. Anschließend schließt die periodische Übertragung mit Zyklus $t_{c1}$ direkt an den letzten Burst-Pfeil an.</li>\n<li><strong>Ereignis während laufendem Zyklus ($V = a$)</strong>: Ein erneutes Ereignis führt nach $dt$ und $t_{r,\\min}$ zu einem weiteren 3-fachen Burst ($t_d$). Der ursprüngliche zyklische Sendezeitpunkt (blau gestrichelt) wird durch den vorangegangenen Burst abgelöst bzw. der Zyklus $t_{c1}$ wird neu synchronisiert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Veranschaulicht normativ die Einhaltung der Minimum Delay Time ($t_{r,\\min}$) sowohl bei Moduswechseln (TMS-Switch) als auch bei ereignisgesteuerten Burst-Wiederholungen im Mixed-Modus.</li>\n<li>Zeigt das deterministische Verhalten für AUTOSAR COM: Ein durch ein Ereignis ausgelöster Burst ($n$ Wiederholungen im Abstand $t_d$) hat Vorrang; nach Abschluss des Bursts wird der periodische Zyklus $t_c$ neu gestartet bzw. weitergeführt.</li>\n<li>Bei der Implementierung ist sicherzustellen, dass keine Aussendung die konfigurierte Mindestzeit $t_{r,\\min}$ unterschreitet, selbst wenn ein periodischer Trigger oder Ereignis-Trigger unmittelbar ansteht.</li>\n</ul>"}, {"id": "FIG-b64885231ba4727f", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Ablaufdiagramm zur Veranschaulichung des Übertragungsmodus „Mixed“ (periodisch mit ereignisgesteuertem Anteil / n-facher Wiederholung) und Umschaltung des Transmission Mode Selector (TMS) im AUTOSAR Communication Modul (AUTOSAR COM, Classic Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitachse</strong>: Horizontale Hauptzeitachse mit Unterbrechungssymbolen (Auslassungen).</li>\n<li><strong>Zustände / Werte</strong>: Signal-/Filterzustand $V = a$ bzw. $V = b$ steuert den aktiven Transmission Mode.</li>\n<li><strong>Sendeereignisse</strong>: Grüne Pfeile (vertikal nach unten) für I-PDU-Übertragungszeitpunkte auf den Bus.</li>\n<li><strong>Auslöser / Trigger</strong>: Rote Blitzsymbole für interne Sendeanforderungen (Ereignisse / Signalaktualisierungen).</li>\n<li><strong>Zeitparameter</strong>:</li>\n<li>$t_{c1}$, $t_{c2}$: Zykluszeiten (Cycle Times) der periodischen Übertragung für die jeweiligen Modi.</li>\n<li>$y \\cdot t_{c1}$, $z \\cdot t_{c2}$: Ganzzahlige Vielfache von Übertragungszyklen zwischen den dargestellten Zeitausschnitten.</li>\n<li>$t_d$: Wiederholzeit (Repetition Period / Delay) für n-fache Bursts ($n = 3$).</li>\n<li>$dt$: Übertragungsdauer / Laufzeit (Transmission Duration).</li>\n<li>$t_{r,\\min}$: Mindestabstandszeit (Minimum Delay Time, MDT) zur Begrenzung der Buslast.</li>\n<li><strong>Sonderdarstellung</strong>: Blau gestrichelter Pfeil markiert einen regulären periodischen Sendezeitpunkt, der durch ein nachfolgendes oder überlappendes Ereignis angepasst wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initiale periodische Aussendung ($V = a$)</strong>: Das I-PDU wird zyklisch im Abstand von $t_{c1}$ übertragen.</li>\n<li><strong>TMS-Umschaltung auf Modus $b$ ($V = b$)</strong>: Ein Signalereignis triggert den Moduswechsel zu $V = b$. Die Übertragung erfolgt nun nach Ablauf der Mindestabstandszeit $t_{r,\\min}$ mit der neuen Zykluszeit $t_{c2}$.</li>\n<li><strong>TMS-Umschaltung zurück auf Modus $a$ mit Burst ($V = a$)</strong>: Ein Ereignis schaltet den Modus zurück auf $a$. Nach Ablauf von $dt$ und Einhaltung von $t_{r,\\min}$ wird ein 3-facher Burst ($n = 3$) mit dem Wiederholabstand $t_d$ gesendet. Anschließend schließt die periodische Übertragung mit Zyklus $t_{c1}$ direkt an den letzten Burst-Pfeil an.</li>\n<li><strong>Ereignis während laufendem Zyklus ($V = a$)</strong>: Ein erneutes Ereignis führt nach $dt$ und $t_{r,\\min}$ zu einem weiteren 3-fachen Burst ($t_d$). Der ursprüngliche zyklische Sendezeitpunkt (blau gestrichelt) wird durch den vorangegangenen Burst abgelöst bzw. der Zyklus $t_{c1}$ wird neu synchronisiert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Veranschaulicht normativ die Einhaltung der Minimum Delay Time ($t_{r,\\min}$) sowohl bei Moduswechseln (TMS-Switch) als auch bei ereignisgesteuerten Burst-Wiederholungen im Mixed-Modus.</li>\n<li>Zeigt das deterministische Verhalten für AUTOSAR COM: Ein durch ein Ereignis ausgelöster Burst ($n$ Wiederholungen im Abstand $t_d$) hat Vorrang; nach Abschluss des Bursts wird der periodische Zyklus $t_c$ neu gestartet bzw. weitergeführt.</li>\n<li>Bei der Implementierung ist sicherzustellen, dass keine Aussendung die konfigurierte Mindestzeit $t_{r,\\min}$ unterschreitet, selbst wenn ein periodischer Trigger oder Ereignis-Trigger unmittelbar ansteht.</li>\n</ul>"}], "trans": [{"from": "FIG-9b642fb2dfc41c15", "to": "FIG-40c0bbdc2d3a7cee", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Typografie und Font-Rendering angepasst: Indizes und Abstände bei Zeitvariablen (u. a. <code>tc1</code>, <code>y*tc1</code>, <code>tr,min</code>, <code>td</code>) sowie Beschriftungspositionierung wurden neu gesetzt.</li>\n</ul>"}, {"from": "FIG-40c0bbdc2d3a7cee", "to": "FIG-b64885231ba4727f", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Typografie und Laufweite einzelner Variablenbeschriftungen (u. a. <code>tc1</code>, <code>y*tc1</code>, <code>tr,min</code>) geringfügig neu ausgerichtet.</li>\n</ul>"}]};
